var dlg = document.getElementById('dlg');
document.getElementById('open').addEventListener('click', function () { dlg.showModal(); });
dlg.addEventListener('close', function () {
  document.getElementById('res').textContent = 'Result: ' + (dlg.returnValue || 'closed with Esc');
});

document.title = 'Changed from JS';
var m = document.createElement('meta'); m.name = 'description'; m.content = 'Added dynamically'; document.head.appendChild(m);
var lines = ['title = ' + document.title,
  'meta tags = ' + document.getElementsByTagName('meta').length,
  'description = ' + document.querySelector('meta[name=description]').content];
lines.forEach(function (t) { var li = document.createElement('li'); li.textContent = t; document.getElementById('o').appendChild(li); });
